--
-- Name: dequeue_jobs(text, text, integer, interval); Type: FUNCTION; Schema: bazaar; Owner: bazaar_owner
--

CREATE FUNCTION bazaar.dequeue_jobs(p_queue text, p_worker text, p_limit integer DEFAULT 1, p_lease interval DEFAULT '00:05:00'::interval) RETURNS SETOF bazaar.jobs
    LANGUAGE sql
    AS $$
    UPDATE jobs j
    SET locked_at = now(),
        locked_by = p_worker,
        attempts  = j.attempts + 1
    WHERE j.id IN (
        SELECT c.id
        FROM jobs c
        WHERE c.queue = p_queue
          AND c.done_at IS NULL
          AND c.run_at <= now()
          AND c.attempts < c.max_attempts
          AND (c.locked_at IS NULL OR c.locked_at < now() - p_lease)  -- free or lease expired
        ORDER BY c.run_at, c.id
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    )
    RETURNING j.*;
$$;


