CREATE FUNCTION bazaar.fail_job(p_id bigint, p_error text) RETURNS boolean
    LANGUAGE sql
    AS $$
    UPDATE jobs
    SET last_error = p_error,
        locked_at  = NULL,
        locked_by  = NULL,
        run_at     = now() + least(interval '10 seconds' * power(2, greatest(attempts - 1, 0)),
                               interval '1 hour')
    WHERE id = p_id
      AND done_at IS NULL
    RETURNING true;
$$;


