--
-- Name: set_updated_at(); Type: FUNCTION; Schema: bazaar; Owner: bazaar_owner
--

CREATE FUNCTION bazaar.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- A BEFORE trigger may modify NEW; the modified row is what gets stored.
    -- now() is the transaction start time, so all rows touched by one
    -- transaction share the same updated_at.
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


