--
-- Name: active_products; Type: VIEW; Schema: bazaar; Owner: bazaar_owner
--

CREATE VIEW bazaar.active_products AS
 SELECT p.id,
    p.seller_id,
    s.shop_name,
    p.category_id,
    c.name AS category_name,
    p.sku,
    p.title,
    p.description,
    p.price,
    p.attributes,
    p.tags,
    COALESCE((i.quantity - i.reserved), 0) AS available,
    p.created_at,
    p.updated_at
   FROM (((bazaar.products p
     JOIN bazaar.sellers s ON ((s.id = p.seller_id)))
     JOIN bazaar.categories c ON ((c.id = p.category_id)))
     LEFT JOIN bazaar.inventory i ON ((i.product_id = p.id)))
  WHERE (p.status = 'active'::bazaar.product_status);


