    id bigint NOT NULL,
    product_id bigint NOT NULL,
    discount_pct numeric(5,2) NOT NULL,
    active_during tstzrange NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT promotions_discount_pct_range CHECK (((discount_pct > (0)::numeric) AND (discount_pct < (100)::numeric))),
    CONSTRAINT promotions_range_not_empty CHECK ((NOT isempty(active_during)))
);


ALTER TABLE bazaar.promotions OWNER TO bazaar_owner;

