--
-- Name: seller_sales_daily; Type: MATERIALIZED VIEW; Schema: bazaar; Owner: bazaar_owner
--

CREATE MATERIALIZED VIEW bazaar.seller_sales_daily AS
 SELECT o.seller_id,
    ((o.created_at AT TIME ZONE 'UTC'::text))::date AS day,
    count(*) AS orders_count,
    sum(i.items) AS items_sold,
    sum(o.total) AS revenue
   FROM (bazaar.orders o
     JOIN ( SELECT order_items.order_id,
            sum(order_items.quantity) AS items
           FROM bazaar.order_items
          GROUP BY order_items.order_id) i ON ((i.order_id = o.id)))
  WHERE (o.status = ANY (ARRAY['paid'::bazaar.order_status, 'shipped'::bazaar.order_status, 'delivered'::bazaar.order_status]))
  GROUP BY o.seller_id, (((o.created_at AT TIME ZONE 'UTC'::text))::date)
  WITH NO DATA;


ALTER MATERIALIZED VIEW bazaar.seller_sales_daily OWNER TO bazaar_owner;

--
-- Name: MATERIALIZED VIEW seller_sales_daily; Type: COMMENT; Schema: bazaar; Owner: bazaar_owner
--

COMMENT ON MATERIALIZED VIEW bazaar.seller_sales_daily IS 'Daily orders/items/revenue per seller (paid+shipped+delivered). Refresh: REFRESH MATERIALIZED VIEW CONCURRENTLY seller_sales_daily;';


