--
-- Name: inventory inventory_seller; Type: POLICY; Schema: bazaar; Owner: bazaar_owner
--

CREATE POLICY inventory_seller ON bazaar.inventory TO bazaar_seller USING ((EXISTS ( SELECT 1
   FROM bazaar.products p
  WHERE ((p.id = inventory.product_id) AND (p.seller_id = bazaar.current_seller_id()))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM bazaar.products p
  WHERE ((p.id = inventory.product_id) AND (p.seller_id = bazaar.current_seller_id())))));


